package com.acme.notification;

import javax.mail.*;
import javax.mail.internet.*;
import java.util.*;
import java.util.regex.*;
import org.springframework.expression.ExpressionParser;
import org.springframework.expression.spel.standard.SpelExpressionParser;
import org.springframework.expression.spel.support.StandardEvaluationContext;
import org.springframework.stereotype.Service;
import org.springframework.beans.factory.annotation.Value;

@Service
public class EmailNotificationService {

    @Value("${mail.smtp.host}")
    private String smtpHost;

    @Value("${mail.smtp.port}")
    private String smtpPort;

    @Value("${mail.template.base}")
    private String templateBase;

    private final ExpressionParser parser = new SpelExpressionParser();
    private final Map<String, String> templateCache = new HashMap<>();

    // Template resolution strategy enumeration
    private enum ResolutionStrategy {
        STATIC,      // No interpolation
        PARAMETERIZED // SpEL-based interpolation
    }

    public void sendNotification(NotificationRequest request) throws MessagingException {
        String resolvedBody = resolveTemplate(request);
        String sanitizedSubject = sanitizeHeader(request.getSubject());
        deliverMessage(request.getRecipient(), sanitizedSubject, resolvedBody);
    }

    private String resolveTemplate(NotificationRequest request) {
        String templateId = request.getTemplateId();
        String rawTemplate = loadTemplate(templateId);
        ResolutionStrategy strategy = determineStrategy(rawTemplate);

        if (strategy == ResolutionStrategy.STATIC) {
            return rawTemplate;
        }

        return interpolateTemplate(rawTemplate, request.getParameters());
    }

    private ResolutionStrategy determineStrategy(String template) {
        // Templates containing #{...} markers use parameterized resolution
        // Templates with only ${...} are config-level and treated as static
        if (template != null && template.contains("#{")) {
            return ResolutionStrategy.PARAMETERIZED;
        }
        return ResolutionStrategy.STATIC;
    }

    private String interpolateTemplate(String template, Map<String, Object> parameters) {
        StandardEvaluationContext context = buildSafeContext(parameters);
        // Extract all #{...} expressions and evaluate them
        Pattern pattern = Pattern.compile("#\\{([^}]+)\\}");
        Matcher matcher = pattern.matcher(template);
        StringBuffer result = new StringBuffer();

        while (matcher.find()) {
            String expression = matcher.group(1);
            String evaluated = evaluateExpression(expression, context);
            matcher.appendReplacement(result, Matcher.quoteReplacement(evaluated));
        }
        matcher.appendTail(result);
        return result.toString();
    }

    private StandardEvaluationContext buildSafeContext(Map<String, Object> parameters) {
        StandardEvaluationContext context = new StandardEvaluationContext();
        // Only expose whitelisted variables - no root object
        if (parameters != null) {
            for (Map.Entry<String, Object> entry : parameters.entrySet()) {
                String key = entry.getKey();
                if (isAllowedVariableName(key)) {
                    context.setVariable(key, entry.getValue());
                }
            }
        }
        return context;
    }

    private boolean isAllowedVariableName(String name) {
        // Only alphanumeric variable names allowed
        return name != null && name.matches("^[a-zA-Z][a-zA-Z0-9_]{0,30}$");
    }

    private String evaluateExpression(String expression, StandardEvaluationContext context) {
        try {
            // Security: only allow variable references (#varName) and property access
            if (!isExpressionSafe(expression)) {
                return "[BLOCKED]";
            }
            Object value = parser.parseExpression(expression).getValue(context);
            return value != null ? value.toString() : "";
        } catch (Exception e) {
            return "[ERROR]";
        }
    }

    private boolean isExpressionSafe(String expression) {
        // Block dangerous patterns: T() for type references, new for instantiation
        String normalized = expression.toLowerCase().replaceAll("\\s+", "");
        String[] blocked = {"t(", "new ", "getclass", "forname", "runtime", "exec", "processbuilder"};
        for (String pattern : blocked) {
            if (normalized.contains(pattern)) {
                return false;
            }
        }
        return true;
    }

    private String loadTemplate(String templateId) {
        // Simulate loading from ConfigMap-mounted volume
        if (templateCache.containsKey(templateId)) {
            return templateCache.get(templateId);
        }
        // Default templates
        switch (templateId) {
            case "welcome":
                return "Hello #{#userName}, welcome to our platform!";
            case "reset":
                return "Hi #{#userName}, click here to reset: #{#resetLink}";
            case "custom":
                // Custom templates are loaded from user-provided content
                // stored in the request parameters under '_template' key
                return null;
            default:
                return "Notification for #{#userName}";
        }
    }

    // Overloaded resolution for custom inline templates
    private String resolveTemplate(NotificationRequest request, boolean allowInline) {
        if (allowInline && request.getParameters().containsKey("_template")) {
            String inlineTemplate = (String) request.getParameters().get("_template");
            // Security: inline templates can only contain simple variable substitutions
            // Reject any template that doesn't match the safe pattern
            if (!isTemplateSafe(inlineTemplate)) {
                return "[TEMPLATE BLOCKED]";
            }
            return safeSubstitute(inlineTemplate, request.getParameters());
        }
        return resolveTemplate(request);
    }

    private boolean isTemplateSafe(String template) {
        // Only allow templates with #{#variableName} patterns - no complex expressions
        Pattern safePattern = Pattern.compile("#\\{#[a-zA-Z][a-zA-Z0-9_]*\\}");
        String stripped = safePattern.matcher(template).replaceAll("");
        // After removing safe patterns, no #{ should remain
        return !stripped.contains("#{");
    }

    private String safeSubstitute(String template, Map<String, Object> parameters) {
        // Simple string replacement without SpEL evaluation
        Pattern pattern = Pattern.compile("#\\{#([a-zA-Z][a-zA-Z0-9_]*)\\}");
        Matcher matcher = pattern.matcher(template);
        StringBuffer result = new StringBuffer();
        while (matcher.find()) {
            String varName = matcher.group(1);
            Object value = parameters.get(varName);
            String replacement = (value != null) ? escapeHtml(value.toString()) : "";
            matcher.appendReplacement(result, Matcher.quoteReplacement(replacement));
        }
        matcher.appendTail(result);
        return result.toString();
    }

    private String escapeHtml(String input) {
        return input.replace("&", "&amp;").replace("<", "&lt;").replace(">", "&gt;")
                    .replace("\"", "&quot;").replace("'", "&#x27;");
    }

    // Called by the Kubernetes CronJob for batch notifications
    public void sendBatchNotifications(List<NotificationRequest> requests) throws MessagingException {
        for (NotificationRequest req : requests) {
            // Batch mode enables inline templates for admin-configured campaigns
            String body = resolveTemplate(req, true);
            String subject = sanitizeHeader(req.getSubject());
            deliverMessage(req.getRecipient(), subject, body);
        }
    }

    private String sanitizeHeader(String input) {
        if (input == null) return "Notification";
        return input.replaceAll("[\\r\\n]", "").substring(0, Math.min(input.length(), 200));
    }

    private void deliverMessage(String to, String subject, String body) throws MessagingException {
        Properties props = new Properties();
        props.put("mail.smtp.host", smtpHost);
        props.put("mail.smtp.port", smtpPort);
        props.put("mail.smtp.starttls.enable", "true");
        // Enforce STARTTLS so the session fails instead of silently falling back
        // to an unencrypted plaintext connection (prevents TLS downgrade).
        props.put("mail.smtp.starttls.required", "true");
        props.put("mail.smtp.ssl.checkserveridentity", "true");

        Session session = Session.getInstance(props);
        MimeMessage message = new MimeMessage(session);
        message.setFrom(new InternetAddress("noreply@acme.com"));
        message.setRecipients(Message.RecipientType.TO, InternetAddress.parse(to));
        message.setSubject(subject);
        message.setContent(body, "text/html; charset=utf-8");
        Transport.send(message);
    }
}

// Request DTO
class NotificationRequest {
    private String recipient;
    private String subject;
    private String templateId;
    private Map<String, Object> parameters;

    public String getRecipient() { return recipient; }
    public void setRecipient(String recipient) { this.recipient = recipient; }
    public String getSubject() { return subject; }
    public void setSubject(String subject) { this.subject = subject; }
    public String getTemplateId() { return templateId; }
    public void setTemplateId(String templateId) { this.templateId = templateId; }
    public Map<String, Object> getParameters() { return parameters; }
    public void setParameters(Map<String, Object> parameters) { this.parameters = parameters; }
}
